#include <stdio.h>

struct Player {
    char name[10];
    int hp;
};

void heal(struct Player *p) {
    // p->hp += 10;
    (*p).hp += 10; // 원래 문법
    p->hp += 10;   // 편리한 문법 (Syntactic Sugar)
}

int main() {
    struct Player warrior = {"Conan", 50};

    printf("HP: %d\n", warrior.hp);
    heal(&warrior); // 주소 전달
    printf("HP: %d\n", warrior.hp);

    return 0;
}
